def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def best_target(targets, sx, sy, mode="min"):
        best = None
        best_score = None
        for t in targets or []:
            tx, ty = pos(t, None) if t is not None else (None, None)
            if tx is None:
                continue
            score = abs(tx - sx) + abs(ty - sy)
            if mode == "max":
                score = -score
            if best is None or score < best_score:
                best = (tx, ty)
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    role = observation.get("self_role", "agent")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return clamp_move(sign(ox - sx), sign(oy - sy))
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best_d = None
        for cx, cy in corners:
            d = abs(cx - ox) + abs(cy - oy)
            if target is None or d > best_d:
                target = (cx, cy)
                best_d = d
        if target is None:
            return clamp_move(-sign(ox - sx), -sign(oy - sy))
        tx, ty = target
        return clamp_move(sign(tx - sx), sign(ty - sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        target = best_target(targets, sx, sy, "min")
        if target is not None:
            tx, ty = target
            return clamp_move(sign(tx - sx), sign(ty - sy))
        return clamp_move(sign(ox - sx), sign(oy - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    target = best_target(resources, sx, sy, "min")
    if target is not None:
        tx, ty = target
        return clamp_move(sign(tx - sx), sign(ty - sy))

    if gw and gh:
        cx = gw // 2
        cy = gh // 2
        return clamp_move(sign(cx - sx), sign(cy - sy))

    return clamp_move(sign(ox - sx), sign(oy - sy))

